@import "tailwindcss";

:root { --ink:#17241d; --muted:#6d776f; --line:#e6e7e2; --paper:#f6f5f0; --white:#fff; --orange:#ed6b35; --orange-dark:#d95624; --green:#1f7a52; --soft-green:#e8f4ed; --yellow:#f4b740; --blue:#3974bf; }
* { box-sizing:border-box; }
html { background:var(--paper); }
body { margin:0; color:var(--ink); background:var(--paper); font-family:Inter, Arial, Helvetica, sans-serif; }
button, input, select, textarea { font:inherit; }
button { cursor:pointer; }
.app-shell { min-height:100vh; display:grid; grid-template-columns:244px 1fr; }
.sidebar { position:sticky; top:0; height:100vh; background:var(--ink); color:#fff; padding:24px 18px 18px; display:flex; flex-direction:column; z-index:10; }
.brand { border:0; background:none; color:inherit; display:flex; align-items:center; gap:10px; font-size:21px; font-weight:750; letter-spacing:-.04em; padding:0; }
.brand-mark { width:34px; height:34px; display:grid; place-items:center; background:var(--orange); color:#fff; border-radius:10px 10px 10px 3px; font-family:Georgia,serif; font-size:22px; font-style:italic; }
.workspace-card { margin:28px 0 18px; padding:11px; background:#24342b; border:1px solid #30453a; border-radius:12px; display:flex; align-items:center; gap:10px; }
.workspace-avatar { width:34px; height:34px; border-radius:9px; background:#f2c9a8; color:#77401f; display:grid; place-items:center; font-size:11px; font-weight:800; }
.workspace-card span:last-child, .user-row span:nth-child(2) { min-width:0; display:flex; flex-direction:column; }
.workspace-card small, .user-row small { font-size:9px; letter-spacing:.11em; color:#aebbb3; margin-bottom:3px; }
.workspace-card strong { font-size:12px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
nav { display:flex; flex-direction:column; gap:4px; }
nav button { width:100%; display:flex; align-items:center; gap:12px; background:transparent; color:#bdc6c0; border:0; padding:11px 12px; border-radius:9px; text-align:left; font-size:13px; }
nav button span { width:18px; text-align:center; color:#91a097; }
nav button:hover, nav button.active { background:#2a3c32; color:#fff; }
nav button.active span { color:#ff9365; }
.sidebar-bottom { margin-top:auto; }
.support-card { background:#f0c7a3; color:#492f1f; border-radius:13px; padding:15px; display:flex; flex-direction:column; margin-bottom:16px; }
.support-card span { font-weight:750; font-size:13px; }.support-card small { font-size:10px; margin:3px 0 12px; opacity:.7; }.support-card button { background:#fff8f1; border:0; padding:8px; border-radius:7px; font-size:10px; font-weight:700; color:#492f1f; }
.user-row { padding-top:15px; border-top:1px solid #314139; display:grid; grid-template-columns:34px 1fr auto; align-items:center; gap:9px; }
.user-row strong { font-size:11px; }.user-row button { background:none; border:0; color:#98a59e; }.user-avatar { width:34px; height:34px; background:#d9e5dd; color:#304b3d; border-radius:50%; display:grid; place-items:center; font-size:10px; font-weight:800; }
.main { min-width:0; }
.topbar { height:88px; display:flex; justify-content:space-between; align-items:center; padding:0 38px; background:#fff; border-bottom:1px solid var(--line); }
.topbar h1 { margin:0; font-size:21px; letter-spacing:-.03em; }.topbar p { margin:4px 0 0; color:var(--muted); font-size:11px; }
.topbar-actions { display:flex; align-items:center; gap:12px; }.portal-switch { display:flex; align-items:center; gap:8px; color:var(--muted); font-size:10px; }.portal-switch select { color:var(--ink); background:#f7f7f4; border:1px solid var(--line); padding:8px 30px 8px 10px; border-radius:8px; font-size:11px; font-weight:650; }
.icon-button { width:36px; height:36px; position:relative; border:1px solid var(--line); background:#fff; border-radius:9px; color:#788078; }.notification-dot { width:6px; height:6px; position:absolute; right:8px; top:7px; background:var(--orange); border-radius:50%; }
.content { padding:30px 38px 52px; max-width:1600px; margin:auto; }
.hero-panel, .welcome-strip { min-height:280px; border-radius:18px; background:var(--ink); color:#fff; padding:38px 44px; display:flex; justify-content:space-between; overflow:hidden; }
.hero-panel>div:first-child { width:58%; position:relative; z-index:2; }.eyebrow { color:var(--orange); font-size:9px; letter-spacing:.16em; font-weight:800; }.hero-panel h2 { font-family:Georgia,serif; font-size:44px; line-height:1.02; font-weight:500; letter-spacing:-.04em; margin:14px 0; }.hero-panel p { max-width:510px; color:#b8c2bb; line-height:1.6; font-size:13px; }.hero-actions { display:flex; gap:10px; margin-top:24px; }
.button { border:0; border-radius:9px; padding:10px 15px; font-size:11px; font-weight:750; transition:.2s ease; }.button:hover { transform:translateY(-1px); }.button.primary { background:var(--orange); color:#fff; }.button.primary:hover { background:var(--orange-dark); }.button.light { background:#fff; color:var(--ink); }.button.ghost-light { background:transparent; border:1px solid #546159; color:#fff; }.button.secondary { background:#fff; border:1px solid #dfe1dc; color:var(--ink); }.button.danger { background:#fff1ec; color:#b84720; border:1px solid #f2c6b5; }.button.danger.subtle { border:0; background:transparent; }.button.small { padding:8px 12px; }.button:disabled { opacity:.45; cursor:not-allowed; transform:none; }.full-button { width:100%; }
.hero-visual { width:34%; position:relative; display:grid; place-items:center; }.hero-logo { position:relative; z-index:2; font:italic 74px Georgia,serif; color:#fff; }.hero-logo span { color:var(--orange); }.orbit { position:absolute; border:1px solid #466052; border-radius:50%; }.orbit-one { width:215px; height:215px; }.orbit-two { width:320px; height:320px; }.float-card { position:absolute; z-index:3; background:#fff; color:var(--ink); padding:10px 13px; border-radius:9px; box-shadow:0 15px 35px #07110c66; font-size:9px; font-weight:750; }.card-a { left:-15px; top:42px; }.card-b { right:-12px; bottom:34px; }
.section { margin-top:30px; }.section-head { display:flex; justify-content:space-between; align-items:center; gap:16px; margin-bottom:17px; }.section-head h2 { font-size:16px; margin:0 0 4px; letter-spacing:-.02em; }.section-head p { font-size:10px; margin:0; color:var(--muted); }.text-button { color:var(--orange-dark); background:none; border:0; font-size:10px; font-weight:750; padding:5px; }
.metric-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:14px; }.metric { background:#fff; border:1px solid var(--line); border-radius:14px; padding:18px; display:flex; align-items:flex-start; gap:14px; }.metric-icon { width:34px; height:34px; display:grid; place-items:center; background:#fff0e9; color:var(--orange-dark); border-radius:9px; font-weight:800; }.metric>span:last-child { display:flex; flex-direction:column; }.metric small { color:var(--muted); font-size:9px; }.metric strong { font-size:24px; margin:5px 0 4px; letter-spacing:-.04em; }.metric em { font-style:normal; font-size:9px; color:var(--green); }
.split { display:grid; grid-template-columns:1.6fr 1fr; gap:16px; }.panel { background:#fff; border:1px solid var(--line); border-radius:14px; padding:20px; }.panel>.section-head { margin-bottom:15px; }
.data-table { overflow-x:auto; }.table-row { min-width:680px; display:grid; grid-template-columns:1.5fr 1.1fr .7fr .45fr .45fr; align-items:center; gap:12px; padding:12px 5px; border-top:1px solid #eeefeb; font-size:10px; }.table-row.table-head { border:0; color:#899089; text-transform:uppercase; letter-spacing:.07em; font-size:8px; padding-top:2px; }.company-cell { display:flex; align-items:center; gap:10px; }.company-cell i { width:34px; height:34px; background:#edf0ec; border-radius:9px; display:grid; place-items:center; font-style:normal; font-size:9px; font-weight:800; }.company-cell span { display:flex; flex-direction:column; }.company-cell small { color:var(--muted); margin-top:3px; }.status { display:inline-flex; width:max-content; border-radius:20px; padding:5px 8px; font-style:normal; font-size:8px; text-transform:capitalize; }.status.active,.status.accepted,.status.served { background:var(--soft-green); color:var(--green); }.status.pending { background:#fff4d8; color:#9a6915; }.status.preparing { background:#eaf1fc; color:var(--blue); }.status.ready { background:#eee9fa; color:#6647a3; }.status.rejected,.status.voided { background:#fff0eb; color:#b94f2a; }
.activity-row { display:flex; align-items:center; gap:12px; border-top:1px solid #eeefeb; padding:14px 2px; }.activity-row i { width:9px; height:9px; border-radius:50%; box-shadow:0 0 0 5px #eee; }.activity-row i.orange { background:var(--orange); box-shadow:0 0 0 5px #fff0e9; }.activity-row i.green { background:var(--green); box-shadow:0 0 0 5px var(--soft-green); }.activity-row i.blue { background:var(--blue); box-shadow:0 0 0 5px #eaf1fc; }.activity-row span { display:flex; flex-direction:column; }.activity-row strong { font-size:10px; }.activity-row small { font-size:9px; color:var(--muted); margin-top:4px; }
.welcome-strip { min-height:205px; align-items:center; background:linear-gradient(105deg,#17241d 0%,#244432 100%); }.welcome-strip h2 { font:500 35px Georgia,serif; margin:12px 0 6px; }.welcome-strip p { color:#bdc8c1; font-size:12px; }.order-mini { display:grid; grid-template-columns:9px 1fr auto; gap:11px; align-items:center; padding:13px 0; border-top:1px solid #eeefeb; }.order-dot { width:8px; height:8px; border-radius:50%; background:#bbb; }.order-dot.pending { background:var(--yellow); }.order-dot.accepted { background:var(--green); }.order-dot.ready { background:#7654b7; }.order-mini span:nth-child(2) { display:flex; flex-direction:column; }.order-mini strong,.order-mini b { font-size:10px; }.order-mini small { color:var(--muted); font-size:9px; margin-top:4px; white-space:nowrap; text-overflow:ellipsis; overflow:hidden; max-width:440px; }.mini-floor { display:grid; grid-template-columns:repeat(3,1fr); gap:9px; }.mini-table { min-height:70px; border:1px solid var(--line); border-radius:10px; display:flex; flex-direction:column; align-items:center; justify-content:center; }.mini-table span { font-weight:800; font-size:11px; }.mini-table small { font-size:8px; text-transform:capitalize; color:var(--muted); margin-top:4px; }.mini-table.open { background:var(--soft-green); border-color:#c6dfd1; }.mini-table.bill_requested { background:#fff4d8; border-color:#f0dcaa; }
.legend { display:flex; gap:13px; font-size:9px; color:var(--muted); }.legend span { display:flex; align-items:center; gap:5px; }.legend-dot { width:7px; height:7px; border-radius:50%; background:#bfc5bf; }.legend-dot.open { background:var(--green); }.legend-dot.bill_requested { background:var(--yellow); }
.table-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:15px; }.table-card { background:#fff; border:1px solid var(--line); border-radius:14px; padding:20px; }.table-card.open { border-top:3px solid var(--green); }.table-card.bill_requested { border-top:3px solid var(--yellow); }.table-card-top { display:flex; justify-content:space-between; align-items:center; }.table-icon { width:34px; height:34px; display:grid; place-items:center; border-radius:9px; background:#eef0ed; font-size:18px; }.table-card-top em { font-size:8px; text-transform:uppercase; letter-spacing:.09em; font-style:normal; color:var(--muted); }.table-card h3 { margin:18px 0 5px; font-size:16px; }.table-card p { color:var(--muted); font-size:9px; margin:0 0 18px; }.dual-actions { display:grid; grid-template-columns:1fr 1fr; gap:8px; }
.live-pill,.success-pill { color:var(--green); background:var(--soft-green); padding:7px 10px; border-radius:20px; font-size:8px; letter-spacing:.1em; font-weight:800; }.order-board { display:grid; grid-template-columns:repeat(3,1fr); gap:14px; align-items:start; }.order-card { background:#fff; border:1px solid var(--line); border-radius:14px; padding:18px; }.order-card-head,.order-card-bottom { display:flex; justify-content:space-between; align-items:center; gap:10px; }.order-card-head>span { display:flex; flex-direction:column; }.order-card-head strong { font-size:14px; }.order-card-head small { color:var(--muted); font-size:9px; margin-top:3px; }.order-card>p { min-height:52px; padding:14px 0; border-block:1px solid #eeefeb; color:#4e5952; font-size:10px; line-height:1.55; }.order-card-bottom>div { display:flex; gap:4px; align-items:center; }.order-card-bottom b { font-size:14px; }
.menu-list { padding:4px 20px; }.menu-admin-row { display:grid; grid-template-columns:42px 1fr auto 42px; align-items:center; gap:12px; padding:13px 0; border-top:1px solid #eeefeb; }.menu-admin-row:first-child { border:0; }.menu-thumb { width:38px; height:38px; display:grid; place-items:center; border-radius:10px; background:#e9dfd3; color:#795d45; font:italic 17px Georgia,serif; }.menu-admin-row>span:nth-child(2) { display:flex; flex-direction:column; }.menu-admin-row strong { font-size:11px; }.menu-admin-row small { color:var(--muted); font-size:9px; margin-top:4px; }.menu-admin-row b { font-size:11px; }.toggle { width:34px; height:19px; padding:2px; border:0; background:#cdd1cd; border-radius:20px; }.toggle i { display:block; width:15px; height:15px; background:#fff; border-radius:50%; transition:.2s; }.toggle.on { background:var(--green); }.toggle.on i { transform:translateX(15px); }
.team-grid { padding:5px 20px; }.member { display:grid; grid-template-columns:38px 1fr auto auto; gap:12px; align-items:center; border-top:1px solid #eeefeb; padding:14px 0; }.member:first-child { border:0; }.member-avatar { width:36px; height:36px; background:#e9eeea; color:#355444; border-radius:50%; display:grid; place-items:center; font-size:9px; font-weight:800; }.member>span:nth-child(2) { display:flex; flex-direction:column; }.member strong { font-size:11px; }.member small { color:var(--muted); font-size:9px; margin-top:3px; }
.finance-chart { margin-top:16px; }.finance-chart>.section-head>strong { font-size:22px; }.bars { height:240px; display:flex; justify-content:space-around; align-items:end; gap:16px; border-bottom:1px solid var(--line); padding:25px 20px 0; }.bars div { height:100%; flex:1; display:flex; flex-direction:column; justify-content:end; align-items:center; gap:8px; }.bars i { display:block; width:100%; max-width:46px; border-radius:6px 6px 0 0; background:linear-gradient(#f48a5c,var(--orange)); }.bars span { font-size:8px; color:var(--muted); transform:translateY(20px); }
.settings-wrap { max-width:760px; }.settings-form { display:grid; grid-template-columns:1fr 1fr; gap:16px; }.settings-form label,.form-grid label { font-size:9px; font-weight:700; color:#49534c; display:flex; flex-direction:column; gap:7px; }.settings-form input,.settings-form select,.form-grid input,.form-grid select,.form-grid textarea { width:100%; border:1px solid #dfe1dc; background:#fbfbf9; border-radius:8px; padding:10px 11px; color:var(--ink); outline:none; }.settings-form input:focus,.form-grid input:focus,.form-grid textarea:focus { border-color:var(--orange); box-shadow:0 0 0 3px #ed6b3515; }.settings-form .button { align-self:end; }
.modal-backdrop { position:fixed; inset:0; background:#08110c99; backdrop-filter:blur(4px); display:grid; place-items:center; padding:20px; z-index:50; }.modal { width:min(560px,100%); max-height:90vh; overflow:auto; background:#fff; border-radius:17px; padding:23px; box-shadow:0 30px 80px #0005; }.modal-head { display:flex; justify-content:space-between; align-items:center; margin-bottom:22px; }.modal-head h2 { font-size:17px; margin:0; }.modal-head button { width:32px; height:32px; border:0; background:#f0f1ee; border-radius:8px; font-size:18px; color:#667068; }.form-grid { display:grid; grid-template-columns:1fr 1fr; gap:14px; }.form-grid .full { grid-column:1/-1; }.modal-actions { display:flex; justify-content:flex-end; gap:8px; margin-top:8px; }.qr-modal { text-align:center; }.qr-modal h3 { font:500 28px Georgia,serif; margin:16px 0 4px; }.qr-modal p { color:var(--muted); font-size:11px; }.qr-modal img { width:min(270px,80%); display:block; margin:15px auto; }.qr-modal>small { display:block; color:var(--muted); font-size:9px; margin-bottom:18px; }.qr-modal .modal-actions { justify-content:center; }.receipt { max-width:370px; margin:auto; }.receipt-brand { text-align:center; border-bottom:1px dashed #cfd2cd; padding-bottom:18px; }.receipt-brand .brand-mark { margin:auto; }.receipt-brand h3 { font:500 24px Georgia,serif; margin:10px 0 4px; }.receipt-brand p,.receipt-note { color:var(--muted); font-size:9px; }.receipt-lines { padding:14px 0; }.receipt-lines span { display:flex; justify-content:space-between; padding:7px 0; font-size:10px; }.receipt-lines .receipt-total { margin-top:8px; padding-top:14px; border-top:2px solid var(--ink); font-size:14px; }.receipt-note { text-align:center; background:#f5f5f1; padding:10px; border-radius:7px; }.toast { position:fixed; right:25px; bottom:25px; z-index:100; background:var(--ink); color:#fff; padding:13px 17px; border-radius:10px; box-shadow:0 10px 35px #0004; font-size:10px; }
.customer-shell { display:block; background:#fbfaf6; }.customer-shell .content { padding:0; max-width:none; }.customer-page { min-height:100vh; }.customer-header { height:78px; display:grid; grid-template-columns:1fr auto 1fr; align-items:center; padding:0 5vw; border-bottom:1px solid #e5e3dc; background:#fbfaf6; }.brand.dark { color:var(--ink); }.customer-company { text-align:center; display:flex; flex-direction:column; }.customer-company small { font-size:7px; letter-spacing:.16em; color:var(--muted); }.customer-company strong { margin-top:3px; font:500 17px Georgia,serif; }.table-badge { justify-self:end; background:var(--ink); color:#fff; padding:8px 12px; border-radius:20px; font-size:9px; font-weight:700; }.customer-hero { padding:60px 6vw 50px; background:linear-gradient(110deg,#f6e7d8 0%,#f5efe3 55%,#e6eadf 100%); position:relative; overflow:hidden; }.customer-hero:after { content:""; position:absolute; width:350px; height:350px; border:70px solid #fff6; border-radius:50%; right:7%; top:-150px; }.customer-hero h1 { position:relative; z-index:1; font:500 52px/1 Georgia,serif; letter-spacing:-.045em; margin:13px 0 15px; }.customer-hero h1 i { color:var(--orange-dark); }.customer-hero p { max-width:525px; color:#5f6a62; font-size:12px; line-height:1.55; }.request-buttons { display:flex; gap:9px; margin-top:22px; position:relative; z-index:2; }.request-buttons button { border:1px solid #d7d5cc; background:#fff9; padding:9px 12px; border-radius:20px; color:var(--ink); font-size:9px; font-weight:700; }.customer-layout { display:grid; grid-template-columns:1fr 315px; gap:30px; padding:32px 5vw 55px; align-items:start; }.category-tabs { display:flex; gap:7px; overflow:auto; padding-bottom:20px; }.category-tabs button { flex:none; border:1px solid #dedfd9; background:#fff; border-radius:20px; padding:8px 13px; font-size:9px; color:#687168; }.category-tabs button.active { background:var(--ink); color:#fff; border-color:var(--ink); }.food-grid { display:grid; grid-template-columns:repeat(2,1fr); gap:16px; }.food-card { display:grid; grid-template-columns:120px 1fr; min-height:170px; background:#fff; border:1px solid #e8e7e1; border-radius:15px; overflow:hidden; }.food-photo { min-height:170px; background:linear-gradient(145deg,#c98b64,#6d402d); display:flex; align-items:end; padding:12px; }.food-photo span { background:#fffD; border-radius:12px; padding:5px 7px; font-size:7px; }.food-1 { background:linear-gradient(145deg,#ceb58b,#655139); }.food-2 { background:linear-gradient(145deg,#e2ae55,#995b2d); }.food-3 { background:linear-gradient(145deg,#b3c28c,#52633c); }.food-card>div:last-child { padding:15px; display:flex; flex-direction:column; }.food-card small { color:var(--orange-dark); text-transform:uppercase; letter-spacing:.1em; font-size:7px; }.food-card h3 { margin:7px 0; font:500 18px Georgia,serif; line-height:1.1; }.food-card p { margin:0; color:var(--muted); font-size:9px; line-height:1.5; }.food-card footer { margin-top:auto; display:flex; justify-content:space-between; align-items:center; }.food-card footer b { font-size:12px; }.food-card footer button { width:30px; height:30px; border:0; border-radius:50%; background:var(--orange); color:#fff; font-size:17px; }.cart { position:sticky; top:20px; background:#fff; border:1px solid #e3e3dc; border-radius:16px; padding:21px; box-shadow:0 12px 35px #33442f0c; }.cart h2 { font:500 25px Georgia,serif; margin:6px 0 18px; }.empty-cart { min-height:180px; display:flex; flex-direction:column; justify-content:center; align-items:center; text-align:center; border-block:1px solid #ecece7; }.empty-cart>span { font-size:28px; color:#aab2aa; }.empty-cart strong { font-size:11px; margin:9px 0 4px; }.empty-cart p { color:var(--muted); font-size:9px; }.cart-items { border-block:1px solid #ecece7; }.cart-items>div { display:flex; justify-content:space-between; gap:10px; padding:12px 0; }.cart-items span { display:flex; flex-direction:column; }.cart-items strong,.cart-items b { font-size:9px; }.cart-items small { color:var(--muted); font-size:8px; margin-top:4px; }.cart-total { display:grid; grid-template-columns:1fr auto; padding:16px 0; font-size:11px; }.cart-total small { grid-column:1/-1; color:var(--muted); font-size:8px; margin-top:7px; }.customer-footer { display:flex; justify-content:space-between; padding:24px 5vw; background:var(--ink); color:#fff; }.customer-footer span { font:500 18px Georgia,serif; }.customer-footer small { color:#aebbb3; font-size:8px; }
@media (max-width:1100px) { .metric-grid { grid-template-columns:repeat(2,1fr); }.table-grid,.order-board { grid-template-columns:repeat(2,1fr); }.customer-layout { grid-template-columns:1fr; }.cart { position:static; }.food-grid { grid-template-columns:repeat(3,1fr); }.food-card { display:block; }.food-photo { min-height:130px; } }
@media (max-width:820px) { .app-shell { display:block; }.sidebar { position:static; width:100%; height:auto; padding:15px; }.sidebar nav { flex-direction:row; overflow:auto; margin-top:14px; }.sidebar nav button { width:auto; white-space:nowrap; }.workspace-card,.sidebar-bottom { display:none; }.topbar { height:auto; padding:18px 20px; align-items:flex-start; }.portal-switch span { display:none; }.content { padding:22px 18px 40px; }.hero-panel { padding:30px; }.hero-panel>div:first-child { width:100%; }.hero-visual { display:none; }.hero-panel h2 { font-size:36px; }.split { grid-template-columns:1fr; }.table-grid,.order-board { grid-template-columns:1fr 1fr; }.customer-header { padding:0 18px; }.customer-hero { padding:44px 20px; }.customer-layout { padding:25px 18px 45px; }.food-grid { grid-template-columns:1fr 1fr; } }
@media (max-width:560px) { .topbar-actions .icon-button { display:none; }.topbar h1 { font-size:17px; }.metric-grid,.table-grid,.order-board { grid-template-columns:1fr; }.hero-panel { min-height:310px; }.hero-panel h2 { font-size:34px; }.hero-actions { flex-direction:column; align-items:stretch; }.legend { display:none; }.form-grid,.settings-form { grid-template-columns:1fr; }.form-grid .full { grid-column:auto; }.customer-header { grid-template-columns:1fr auto; }.customer-company { display:none; }.customer-hero h1 { font-size:42px; }.request-buttons { flex-direction:column; align-items:flex-start; }.food-grid { grid-template-columns:1fr; }.food-card { display:grid; }.customer-footer { flex-direction:column; gap:8px; }.metric strong { font-size:21px; } }
@media print { .sidebar,.topbar,.modal-head,.modal-actions,.toast { display:none !important; }.app-shell { display:block; }.content { display:none; }.modal-backdrop { position:static; background:#fff; padding:0; }.modal { box-shadow:none; max-height:none; width:100%; }.qr-modal img { width:300px; }.receipt { padding-top:30px; } }
